<script setup>
// Reference SHA-256: 4EADBB9CAA596393D67C69CA4F446DBAD38856D2CFF2687E1530F9B8C9EC9E3D
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { PROJECT_FIXTURES, createTalentProjectController } from '../state/talent-project-controller.js';
import { routeSession } from '../state/session-store.js';
import PaginationControl from '../components/PaginationControl.vue';

const props=defineProps({integrationData:{type:Object,default:null},integrationState:{type:String,default:'mock'}});
const controller=routeSession.controller('talent-projects',()=>createTalentProjectController(PROJECT_FIXTURES));
const remoteMode=computed(()=>props.integrationState!=='mock');
const remoteState=computed(()=>props.integrationState);
const mapRemoteProject=item=>({id:item.projectId||item.id,name:item.name||'—',department:'—',owner:item.ownerName||'—',description:item.type||'—',date:item.startDate||'—',progress:item.status||'—',domain:item.type||'—',technology:'—',manager:item.ownerName||'—',members:'—',scale:'—',difficulty:'—'});
const pageState=computed(()=>{if(!remoteMode.value)return 'normal';if(['error','timeout','rate-limited','schema-drift','security-error'].includes(remoteState.value))return 'error';if(['authentication-required','permission-denied'].includes(remoteState.value))return 'permission-denied';if(remoteState.value==='disabled')return 'disabled';if(remoteState.value==='loading')return 'loading';return controller.fixtures.length?'normal':'empty';});
watch([()=>props.integrationData,()=>props.integrationState],()=>{controller.fixtures=remoteMode.value?(Array.isArray(props.integrationData?.['TAL-002']?.items)?props.integrationData['TAL-002'].items.map(mapRemoteProject):[]):PROJECT_FIXTURES.map(item=>({...item}));controller.page=1;},{immediate:true});
const queryDraft=ref(controller.filters.query);
const dialogRef=ref(null);
const firstFieldRef=ref(null);
const closeButtonRef=ref(null);
const resultTitleRef=ref(null);
let opener=null;
let drawerScrollTop=0;
const backgroundInertState=new Map();
const pagedProjects=computed(()=>controller.pagedResults);
const progresses=[...new Set(PROJECT_FIXTURES.map(item=>item.progress))];
const domains=[...new Set(PROJECT_FIXTURES.map(item=>item.domain))];
const managers=[...new Set(PROJECT_FIXTURES.map(item=>item.manager))];

function setBackgroundInert(value){document.querySelectorAll('.topbar,.sidebar').forEach(node=>{if(value){if(!backgroundInertState.has(node))backgroundInertState.set(node,node.hasAttribute('inert'));node.setAttribute('inert','');return;}if(backgroundInertState.get(node))node.setAttribute('inert','');else node.removeAttribute('inert');});if(!value)backgroundInertState.clear();}
function writeDrawerQuery(value,mode='replace'){
  const next=new URL(window.location.href);value?next.searchParams.set('drawer',value):next.searchParams.delete('drawer');
  const state=value?{...window.history.state,xltProjectDrawer:value,xltDrawerPushed:mode==='push'}:{...window.history.state,xltProjectDrawer:undefined,xltDrawerPushed:false};
  if(mode==='push')window.history.pushState(state,'',`${next.pathname}${next.search}`);else window.history.replaceState(state,'',`${next.pathname}${next.search}`);
}
async function focusDrawer(){await nextTick();(controller.mode==='create'?firstFieldRef.value:closeButtonRef.value)?.focus();}
async function restoreOrigin(){await nextTick();const main=document.getElementById('main-content');if(main)main.scrollTop=drawerScrollTop;if(opener?.isConnected)opener.focus();else resultTitleRef.value?.focus();}
async function openCreate(event){if(remoteMode.value){controller.announcement='正式人才写入合同尚未提供';return;}opener=event?.currentTarget||null;drawerScrollTop=document.getElementById('main-content')?.scrollTop||0;controller.openCreate();writeDrawerQuery('create','push');setBackgroundInert(true);await focusDrawer();}
async function openEdit(project,event){if(remoteMode.value){controller.announcement='正式人才写入合同尚未提供';return;}opener=event?.currentTarget||null;drawerScrollTop=document.getElementById('main-content')?.scrollTop||0;controller.openEdit(project.id);writeDrawerQuery(project.id,'push');setBackgroundInert(true);await focusDrawer();}
async function closeDrawer(){if(window.history.state?.xltProjectDrawer&&window.history.state?.xltDrawerPushed&&window.history.length>1){window.history.back();return;}writeDrawerQuery('');controller.close();setBackgroundInert(false);await restoreOrigin();}
async function syncDrawer(){const value=new URLSearchParams(window.location.search).get('drawer');if(value){value==='create'?controller.openCreate():controller.openEdit(value);setBackgroundInert(true);await focusDrawer();}else{const wasOpen=controller.drawerOpen;controller.close();setBackgroundInert(false);if(wasOpen)await restoreOrigin();}}
function submitFilters(){controller.setFilter('query',queryDraft.value);}
function resetFilters(){queryDraft.value='';controller.resetFilters();}
function setFilter(key,event){controller.setFilter(key,event.target.value);}
function setDraft(key,event){controller.setDraft(key,event.target.value);}
async function focusFirstError(){await nextTick();dialogRef.value?.querySelector(`[name="${controller.firstError}"]`)?.focus();}
async function saveTask(){if(!controller.save()){await focusFirstError();return;}await closeDrawer();}
function trapFocus(event){if(event.key!=='Tab'||!dialogRef.value)return;const nodes=[...dialogRef.value.querySelectorAll('button,input,select,textarea,[href],[tabindex]:not([tabindex="-1"])')].filter(node=>!node.disabled);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}

onMounted(()=>{syncDrawer();window.addEventListener('popstate',syncDrawer);});
onBeforeUnmount(()=>{window.removeEventListener('popstate',syncDrawer);setBackgroundInert(false);});
</script>

<template>
  <article class="talent-projects" aria-labelledby="projects-title" @keydown.esc="controller.drawerOpen && closeDrawer()"><p class="sr-only" aria-live="polite">{{ controller.announcement }}</p><nav class="talent-local-nav" :inert="controller.drawerOpen" aria-label="人才管理页面"><span>人才管理</span><a href="/talent/people">人才库</a><a href="/talent/projects" aria-current="page">人才项目管理</a><a href="/talent/progress">项目进度管理</a></nav><section v-if="pageState==='loading'" class="project-empty" role="status">正在加载人才项目的受控只读数据…</section><section v-else-if="pageState==='permission-denied'" class="project-empty" role="alert">需要完成飞书授权或获得人才只读权限后才能查看数据。</section><section v-else-if="pageState==='error'" class="project-empty" role="alert">人才项目数据暂不可用，请稍后重试。</section><section v-else-if="pageState==='disabled'" class="project-empty" role="status">人才真实读取尚未启用；正式人才写入合同尚未提供。</section><section v-else-if="pageState==='empty'" class="project-empty" role="status">当前没有可展示的真实人才项目。</section><div v-else class="projects-body" :class="{'drawer-open':controller.drawerOpen}"><main :inert="controller.drawerOpen"><header><div><h1 id="projects-title">人才项目管理</h1><p>用于管理和跟踪公司内各项人才培养与发展项目，支持项目全生命周期管理。</p></div><button type="button" :disabled="remoteMode" :title="remoteMode?'正式人才写入合同尚未提供':''" @click="openCreate">新增任务</button></header>
      <form aria-label="人才项目筛选" @submit.prevent="submitFilters" @reset.prevent="resetFilters"><label class="search"><span class="sr-only">项目关键词</span><input v-model="queryDraft" type="search" placeholder="请输入项目名称、编号或关键字"/></label><label>项目进度<select :value="controller.filters.progress" @change="setFilter('progress',$event)"><option value="">全部</option><option v-for="value in progresses" :key="value">{{ value }}</option></select></label><label>业务领域<select :value="controller.filters.domain" @change="setFilter('domain',$event)"><option value="">全部</option><option v-for="value in domains" :key="value">{{ value }}</option></select></label><label>项目经理<select :value="controller.filters.manager" @change="setFilter('manager',$event)"><option value="">全部</option><option v-for="value in managers" :key="value">{{ value }}</option></select></label><label>状态<select :value="controller.filters.status" @change="setFilter('status',$event)"><option value="">全部</option><option v-for="value in progresses" :key="value">{{ value }}</option></select></label><button type="submit">查询</button><button type="reset">重置</button></form>
      <section aria-labelledby="project-results-title"><h2 id="project-results-title" ref="resultTitleRef" class="sr-only" tabindex="-1">人才项目结果，共 {{ controller.results.length }} 条</h2><div class="table-scroll" tabindex="0"><table><caption class="sr-only">人才项目管理列表</caption><thead><tr><th scope="col">任务编号</th><th scope="col">需求名称</th><th scope="col">需求部门</th><th scope="col">需求提出人</th><th scope="col">需求描述</th><th scope="col">任务提出日期</th><th scope="col">项目进度</th><th scope="col">业务领域</th><th scope="col">技术类型</th><th scope="col">项目经理</th><th scope="col">项目成员</th><th scope="col">规模等级</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="project in pagedProjects" :key="project.id"><td>{{ project.id }}</td><td>{{ project.name }}</td><td>{{ project.department }}</td><td>{{ project.owner }}</td><td>{{ project.description }}</td><td>{{ project.date }}</td><td>{{ project.progress }}</td><td>{{ project.domain }}</td><td>{{ project.technology }}</td><td>{{ project.manager }}</td><td>{{ project.members }}</td><td>{{ project.scale }}</td><td><button type="button" @click="openEdit(project,$event)">查看</button><button type="button" @click="openEdit(project,$event)">编辑</button><button type="button" @click="controller.announcement=`${project.name}：无更多冻结操作`">更多</button></td></tr></tbody></table></div><p v-if="!controller.results.length" class="project-empty">暂无符合条件的人才项目</p><PaginationControl :total="controller.results.length" :page="controller.page" :page-size="controller.pageSize" label="人才项目分页" @update:page="controller.setPage" @update:page-size="controller.setPageSize" /></section></main>
      <aside v-if="controller.drawerOpen" ref="dialogRef" role="dialog" aria-modal="true" aria-labelledby="project-drawer-title" @keydown="trapFocus"><header><h2 id="project-drawer-title">{{ controller.mode==='create'?'新增任务':'编辑任务' }}</h2><button ref="closeButtonRef" class="drawer-close" type="button" aria-label="关闭任务抽屉" @click="closeDrawer"><span class="sr-only">关闭</span></button></header><form novalidate @submit.prevent="saveTask"><label>任务编号<input name="id" disabled :value="controller.draft.id" placeholder="系统自动生成"/></label><label>需求名称 *<input ref="firstFieldRef" name="name" :value="controller.draft.name" :aria-invalid="Boolean(controller.errors.name)" aria-describedby="error-name" @input="setDraft('name',$event)"/><small id="error-name">{{ controller.errors.name }}</small></label><label>需求部门 *<input name="department" :value="controller.draft.department" @input="setDraft('department',$event)"/></label><label>需求提出人 *<input name="owner" :value="controller.draft.owner" @input="setDraft('owner',$event)"/></label><label>需求描述 *<textarea name="description" :value="controller.draft.description" @input="setDraft('description',$event)"></textarea></label><label>任务提出日期 *<input name="date" type="date" :value="controller.draft.date" @input="setDraft('date',$event)"/></label><label>项目进度 *<select name="progress" :value="controller.draft.progress" @change="setDraft('progress',$event)"><option value="">请选择项目进度</option><option>待启动</option><option>进行中</option><option>已完成</option></select></label><label>业务领域 *<input name="domain" :value="controller.draft.domain" @input="setDraft('domain',$event)"/></label><label>技术类型 *<input name="technology" :value="controller.draft.technology" @input="setDraft('technology',$event)"/></label><label>项目经理 *<input name="manager" :value="controller.draft.manager" @input="setDraft('manager',$event)"/></label><label>项目成员 *<input name="members" :value="controller.draft.members" @input="setDraft('members',$event)"/></label><label>规模等级 *<select name="scale" :value="controller.draft.scale" @change="setDraft('scale',$event)"><option value="">请选择规模</option><option>小型</option><option>中型</option><option>大型</option></select></label><label>难度等级 *<select name="difficulty" :value="controller.draft.difficulty" @change="setDraft('difficulty',$event)"><option value="">请选择难度</option><option>简单</option><option>中等</option><option>复杂</option></select></label><footer><button type="button" @click="closeDrawer">取消</button><button type="button" @click="controller.resetDraft">重置</button><button type="submit">保存</button></footer></form></aside></div></article>
</template>

<style scoped>
.talent-projects{padding:12px 18px;color:#17304f}.talent-projects>nav{font-size:10px}.projects-body{display:grid;grid-template-columns:1fr;gap:12px;margin-top:10px}.projects-body.drawer-open{grid-template-columns:minmax(0,1fr) 380px}.projects-body>main{padding:18px;background:#fff;border:1px solid #dce5ef}.projects-body main>header{display:flex;justify-content:space-between}.projects-body h1{margin:0;font-size:23px}.projects-body header p{font-size:10px}.projects-body main>header button{height:36px;padding:0 22px;color:#fff;background:#0060a6;border:0}.projects-body main>form{display:grid;grid-template-columns:1.4fr repeat(4,1fr) auto auto;gap:12px;margin:28px 0}.projects-body main>form input,.projects-body main>form select,.projects-body main>form button{height:35px;min-width:0;border:1px solid #d8e2ec}.projects-body main>form label{display:flex;align-items:center;gap:5px;font-size:9px}.projects-body main>form .search input{width:100%}.table-scroll{overflow:auto}.projects-body table{width:100%;min-width:1100px;border-collapse:collapse;font-size:8px}.projects-body th,.projects-body td{height:75px;padding:0 8px;border-bottom:1px solid #e1e8ef;text-align:left}.projects-body th{height:45px;background:#f5f7fa}.projects-body td button{padding:0 3px;color:#0060a6;background:none;border:0}.projects-body section>footer{padding:18px;display:flex;justify-content:space-between}.projects-body section>footer nav{display:flex;gap:6px}.projects-body section>footer button{height:30px;border:1px solid #d8e2ec;background:#fff}.projects-body section>footer button[aria-current=page]{color:#fff;background:#0060a6}.projects-body>aside{max-height:calc(100vh - 100px);overflow:auto;background:#fff;border:1px solid #dce5ef}.projects-body>aside>header{position:sticky;top:0;z-index:1;display:flex;justify-content:space-between;padding:10px 18px;background:#fff;border-bottom:1px solid #e1e8ef}.projects-body>aside h2{font-size:15px}.drawer-close{width:24px;height:24px;position:relative;border:0;background:none}.drawer-close::before,.drawer-close::after{content:'';position:absolute;left:11px;top:4px;width:1px;height:15px;background:#17304f}.drawer-close::before{transform:rotate(45deg)}.drawer-close::after{transform:rotate(-45deg)}.projects-body>aside form{padding:15px}.projects-body>aside label{position:relative;display:grid;grid-template-columns:95px 1fr;align-items:center;min-height:51px;font-size:10px}.projects-body>aside input,.projects-body>aside select,.projects-body>aside textarea{height:34px;padding:7px;border:1px solid #d8e2ec}.projects-body>aside textarea{height:70px}.projects-body>aside label small{grid-column:2;color:#c62828}.projects-body>aside footer{position:sticky;bottom:0;display:flex;justify-content:flex-end;gap:15px;padding:12px 0;background:#fff}.projects-body>aside footer button{height:35px;padding:0 24px;color:#0060a6;background:#fff;border:1px solid #d8e2ec}.projects-body>aside footer button[type=submit]{color:#fff;background:#0060a6}.project-empty{padding:50px;text-align:center}.sr-only{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0,0,0,0)}button:focus-visible,a:focus-visible,[tabindex]:focus-visible{outline:3px solid #ff9f1a;outline-offset:2px}@media(max-width:1000px){.projects-body,.projects-body.drawer-open{grid-template-columns:1fr}.projects-body main>form{grid-template-columns:1fr 1fr}}
.projects-body main>form{grid-template-columns:minmax(280px,1.5fr) repeat(4,minmax(160px,1fr)) 80px 80px;align-items:center;gap:14px;padding:12px 14px;background:#f8fafc;border:1px solid #dce5ef;border-radius:6px}.projects-body main>form input,.projects-body main>form select,.projects-body main>form button{height:42px;padding:0 10px;font-size:14px}.projects-body main>form label{gap:7px;font-size:14px;line-height:1.5;white-space:nowrap}.projects-body main>header p{font-size:14px;line-height:1.6}.projects-body main>header button{height:42px;font-size:14px;border-radius:4px}.projects-body table{font-size:12px}.projects-body th{font-size:13px}.projects-body td button{font-size:13px}.projects-body.drawer-open{grid-template-columns:minmax(0,1fr) clamp(520px,38vw,680px)}.projects-body>aside h2{font-size:20px}.projects-body>aside label{grid-template-columns:120px minmax(0,1fr);min-height:58px;font-size:14px}.projects-body>aside input,.projects-body>aside select{height:42px;font-size:14px}.projects-body>aside textarea{height:84px;font-size:14px}.projects-body>aside footer button{height:42px;font-size:14px}@media(max-width:1600px) and (min-width:1001px){.projects-body main>form{grid-template-columns:repeat(4,minmax(0,1fr))}.projects-body main>form .search{grid-column:span 2}}@media(max-width:1180px){.projects-body,.projects-body.drawer-open{grid-template-columns:1fr}}
@media(max-width:1350px){.projects-body main>form{grid-template-columns:repeat(2,minmax(0,1fr))}.projects-body main>form .search{grid-column:1/-1}.projects-body main>form label{min-width:0}.projects-body main>form label select{flex:1}}
.talent-projects :is(.projects-body>main,.projects-body>aside,.projects-body main>form input,.projects-body main>form select,.projects-body main>form button,.projects-body th,.projects-body td,.projects-body section>footer button,.projects-body>aside>header,.projects-body>aside input,.projects-body>aside select,.projects-body>aside textarea,.projects-body>aside footer button){border-color:#f4faff}
</style>
